      "path": "src/adapter/live.ts",
      "content": "/**\n * Live agent projection: derives a TUI-facing view of one agent's live state\n * from the `agent/*` event stream (`agent/status`, `agent/inbox/*`,\n * `agent/error`, `agent/disposed`). No new event vocabulary is invented and no\n * state is written back — the events are the fact source, this is a projection.\n *\n * Two layers mirror the transcript module: a pure fold (`emptyLiveState` /\n * `applyLiveEvent`) and a live subscription wrapper (`trackAgent`).\n *\n * @module @deepseek-ai/dsh-tianshu-tui/adapter/live\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { AgentStatus } from '@deepseek-ai/dsh-agent'\nimport type { ToolCallId } from '@deepseek-ai/dsh-llm'\nimport type { SessionEvent, SessionId, UserMessage } from '@deepseek-ai/dsh-session'\n\n/** One surfaced agent error with its in-turn position. */\nexport interface LiveError {\n  readonly turn: number\n  readonly step: number\n  readonly error: unknown\n}\n\n/** The tool call currently executing, projected from `tool/call` until its `tool/result`. */\nexport interface LiveActivity {\n  readonly callId: ToolCallId\n  /** Tool name as the model produced it. */\n  readonly name: string\n  /** Raw arguments JSON string, exactly as the model produced it (unparsed). */\n  readonly arguments: string\n  readonly turn: number\n  readonly step: number\n}\n\n/** The derived, read-only live state of one agent. */\nexport interface LiveAgentState {\n  readonly id: SessionId\n  /** The agent's lifecycle status (`idle` ⇄ `running`). */\n  readonly status: AgentStatus\n  /** Messages currently pending in the inbox, in insertion order. */\n  readonly inbox: readonly UserMessage[]\n  /** The last surfaced error; cleared when the agent next starts running. */\n  readonly lastError: LiveError | undefined\n  /** Whether the agent is still registered (unset on `agent/disposed`). */\n  readonly live: boolean\n  /** The tool call currently executing, or undefined when none is in flight. */\n  readonly activity: LiveActivity | undefined\n}\n\n/**\n * An empty live state for `id`, with no event yet folded.\n * @param id - 被追踪的 agent/会话 id。\n * @returns idle、空 inbox、live=true 的初始状态。\n */\nexport function emptyLiveState(id: SessionId): LiveAgentState {\n  return { id, status: 'idle', inbox: [], lastError: undefined, live: true, activity: undefined }\n}\n\n/** Remove a message by identity from the pending inbox list. */\nfunction withoutMessage(inbox: readonly UserMessage[], id: string): readonly UserMessage[] {\n  return inbox.filter(message => message.id !== id)\n}\n\n/**\n * Fold one agent-scoped event into the derived state. Returns a NEW state.\n * @param state - the previous derived state.\n * @param event - one discriminated agent event: status, inbox mutation,\n *   tool activity, error, or disposal. Payloads for other agents are filtered\n *   by the caller.\n * @returns the folded state.\n */\nexport function applyLiveEvent(\n  state: LiveAgentState,\n  event:\n    | { type: 'status'; status: AgentStatus }\n    | { type: 'inbox-inserted'; message: UserMessage }\n    | { type: 'inbox-claimed'; messageId: string }\n    | { type: 'inbox-discarded'; messageId: string }\n    | { type: 'tool-call'; turn: number; step: number; callId: ToolCallId; name: string; arguments: string }\n    | { type: 'tool-result'; callId: ToolCallId }\n    | { type: 'error'; turn: number; step: number; error: unknown }\n    | { type: 'disposed' },\n): LiveAgentState {\n  switch (event.type) {\n    case 'status':\n      // 进入 running 清掉上一轮的错误：错误已在 live 区展示，不随重试残留\n      return event.status === 'running'\n        ? { ...state, status: event.status, lastError: undefined }\n        : { ...state, status: event.status }\n    case 'inbox-inserted':\n      return { ...state, inbox: [...state.inbox, event.message] }\n    case 'inbox-claimed':\n    case 'inbox-discarded':\n      return { ...state, inbox: withoutMessage(state.inbox, event.messageId) }\n    case 'tool-call':\n      return {\n        ...state,\n        activity: { callId: event.callId, name: event.name, arguments: event.arguments, turn: event.turn, step: event.step },\n      }\n    case 'tool-result':\n      return state.activity?.callId === event.callId\n        ? { ...state, activity: undefined }\n        : state\n    case 'error':\n      return { ...state, lastError: { turn: event.turn, step: event.step, error: event.error } }\n    case 'disposed':\n      return { ...state, live: false }\n  }\n}\n\n/** A live projection bound to one agent id. */\nexport interface LiveAgent {\n  /** The current derived state; refreshed after every folded event. */\n  readonly state: LiveAgentState\n  /** Detach the `agent/*` subscriptions. Safe once; idempotent. */\n  dispose(): void\n}\n\n/**\n * Track one agent's live state. Seeds from the registry when the agent is\n * already live; thereafter folds every matching `agent/*` event. The caller\n * owns the agent handle it may hold — this projection never disposes it.\n * @param ctx - any context of the app; used to subscribe to `agent/*` events\n *   (globally dispatched, so events are filtered by agent id here).\n * @param id - the agent/session id to track.\n * @returns the live projection; call `dispose()` to detach.\n */\nexport function trackAgent(ctx: Context, id: SessionId): LiveAgent {\n  const seeded = ctx.agents.get(id)\n  let state: LiveAgentState = {\n    ...emptyLiveState(id),\n    status: seeded?.status ?? 'idle',\n    live: seeded !== undefined,\n    inbox: seeded === undefined\n      ? []\n      : [...seeded.inbox.nextTurn, ...seeded.inbox.nextStep],\n  }\n\n  const onStatus = ({ agent, status }: { agent: { id: SessionId }; status: AgentStatus }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'status', status })\n  }\n  const onInserted = ({ agent, message }: { agent: { id: SessionId }; message: UserMessage }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'inbox-inserted', message })\n  }\n  const onClaimed = ({ agent, message }: { agent: { id: SessionId }; message: UserMessage }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'inbox-claimed', messageId: message.id })\n  }\n  const onDiscarded = ({ agent, message }: { agent: { id: SessionId }; message: UserMessage }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'inbox-discarded', messageId: message.id })\n  }\n  const onError = ({ agent, turn, step, error }: { agent: { id: SessionId }; turn: number; step: number; error: unknown }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'error', turn, step, error })\n  }\n  const onDisposed = ({ agent }: { agent: { id: SessionId } }): void => {\n    if (agent.id !== id) return\n    state = applyLiveEvent(state, { type: 'disposed' })\n  }\n  const onSessionEvent = (owner: { id: SessionId }, event: SessionEvent): void => {\n    if (owner.id !== id) return\n    switch (event.type) {\n      case 'tool/call':\n        state = applyLiveEvent(state, {\n          type: 'tool-call',\n          turn: event.data.turn,\n          step: event.data.step,\n          callId: event.data.callId,\n          name: event.data.name,\n          arguments: event.data.arguments,\n        })\n        break\n      case 'tool/result':\n        // ToolResultMessage 的 source 恒为 tool 源，callId 直接可取。\n        state = applyLiveEvent(state, { type: 'tool-result', callId: event.data.message.source.callId })\n        break\n      default:\n        // 其余 session 事件与活动投影无关。\n        break\n    }\n  }\n\n  const disposers = [\n    ctx.on('agent/status', onStatus),\n    ctx.on('agent/inbox/inserted', onInserted),\n    ctx.on('agent/inbox/claimed', onClaimed),\n    ctx.on('agent/inbox/discarded', onDiscarded),\n    ctx.on('agent/error', onError),\n    ctx.on('agent/disposed', onDisposed),\n    ctx.on('session/event', onSessionEvent),\n  ]\n\n  return {\n    get state(): LiveAgentState { return state },\n    dispose(): void {\n      for (const dispose of disposers) dispose()\n    },\n  }\n}\n"
    },
    {
      "path": "src/adapter/send.ts",
      "content": "/**\n * TUI output control surface: turns user intent into driver input through the\n * {@link Agent} public interface. A handle-created agent is driven through the\n * handle the TUI itself owns; a switched-to session is driven through the bare\n * agent returned by `ctx.agents.get(id)` and is NEVER disposed here (only the\n * handle holder — the structural owner — may tear an agent down). This module\n * writes no session events directly: `followup`/`steer`/`inject` submit inbox\n * input that the agent loop logs through its own durable channels.\n *\n * @module @deepseek-ai/dsh-tianshu-tui/adapter/send\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { createUserMessage, type ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { Agent, AgentCancelCause, AgentHandle, CancelOptions } from '@deepseek-ai/dsh-agent'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport type { AttachmentStore, ImageMediaType, SaveImageAttachment } from '@deepseek-ai/dsh-attachment'\n\n/** 解析 data URL（`data:<mediaType>;base64,<bytes>`）为 attachment 保存入参。 */\nfunction parseImageDataUrl(dataUrl: string): SaveImageAttachment {\n  const match = /^data:([a-zA-Z0-9./+-]+);base64,(.+)$/.exec(dataUrl)\n  if (match === null) {\n    throw new Error(`无法解析图片 data URL（缺 base64 载荷）：${dataUrl.slice(0, 40)}…`)\n  }\n  const mediaType = match[1]\n  const payload = match[2]\n  if (mediaType === undefined || payload === undefined) {\n    // 正则匹配成功时两组必然存在；显式收窄以通过严格类型检查。\n    throw new Error(`无法解析图片 data URL（分组缺失）：${dataUrl.slice(0, 40)}…`)\n  }\n  if (!['image/png', 'image/jpeg', 'image/webp', 'image/gif'].includes(mediaType)) {\n    throw new Error(`不支持的图片 media type：${mediaType}`)\n  }\n  return {\n    data: Buffer.from(payload, 'base64'),\n    mediaType: mediaType as ImageMediaType,\n  }\n}\n\n/** Build an identified text-only user message (synchronous fast path). */\nfunction toUserMessageSync(text: string): ReturnType<typeof createUserMessage> {\n  return createUserMessage({ content: [{ type: 'text' as const, text }], source: { kind: 'user' } })\n}\n\n/**\n * Build an identified user message from plain TUI input text + optional image\n * attachments. Images arrive as data URLs (paste/attach pipeline) and are\n * durably committed through the attachment service before the message is\n * published, so the message content carries only the stable reference.\n * @param ctx - context exposing `ctx.attachments` (fails loud when absent).\n * @param text - the prompt text.\n * @param images - optional image data URLs, committed in order.\n * @returns the identified user message with attachment-backed image blocks.\n */\nasync function toUserMessage(ctx: Context, text: string, images?: string[]): Promise<ReturnType<typeof createUserMessage>> {\n  if (images === undefined || images.length === 0) return toUserMessageSync(text)\n  const content: ContentBlock[] = [{ type: 'text' as const, text }]\n  const attachments = ctx.reflect.get('attachments', false) as AttachmentStore | undefined\n  if (attachments === undefined) {\n    throw new Error('图片发送需要 attachments 服务（attachment-local 未装配）')\n  }\n  for (const dataUrl of images) {\n    const attachment = await attachments.saveImage(parseImageDataUrl(dataUrl))\n    content.push({ type: 'image', attachment })\n  }\n  return createUserMessage({ content, source: { kind: 'user' } })\n}\n\n/**\n * The driver-control face of one agent. Methods mirror the bare\n * {@link Agent} interface and carry the same semantics; they accept plain\n * text and construct the identified user message at the call site.\n */\nexport interface AgentControls {\n  /**\n   * Queue an ordinary follow-up turn and wake the driver. Image data URLs are\n   * committed through the attachment service before delivery.\n   * @param text - the prompt text, submitted as a user message.\n   * @param images - optional image attachment data URLs, submitted as image blocks.\n   * @returns fulfillment after images are committed and the message is queued.\n   */\n  followup(text: string, images?: string[]): Promise<void>\n  /**\n   * Submit steering for the nearest step.\n   * @param text - the steering text, submitted as a user message.\n   */\n  steer(text: string): void\n  /**\n   * Queue model-facing context without waking the driver.\n   * @param text - the injected context, submitted as a user message.\n   */\n  inject(text: string): void\n  /**\n   * Abort the active turn or between-turn task.\n   * @param cause - the stable caller intent carried by the cancellation.\n   * @param options - cancellation options; `keepInbox` preserves pending work.\n   */\n  cancel(cause: AgentCancelCause, options?: CancelOptions): void\n  /**\n   * Resolve after the whole-agent activity reaches quiescence.\n   * @returns fulfillment after no active driver or maintenance task remains.\n   */\n  whenIdle(): Promise<void>\n}\n\n/**\n * Build controls for an agent the caller OWNS through a handle. The handle\n * itself is intentionally not exposed here — disposal stays with the holder\n * (`handle.dispose()`); this surface only drives the agent.\n * @param handle - the owned handle returned by `ctx.agents.create`/`resume`.\n * @returns the drive-only control surface over `handle.agent`.\n */\nexport function controlsFromHandle(handle: AgentHandle): AgentControls {\n  return controlsFromAgent(handle.agent)\n}\n\n/**\n * Build controls for a bare agent the caller does NOT own. Never disposes the\n * agent: teardown of a switched-to session belongs to its structural owner.\n * @param agent - a bare agent, e.g. from `ctx.agents.get(id)`.\n * @returns the drive-only control surface over the agent.\n */\nexport function controlsFromAgent(agent: Agent): AgentControls {\n  return {\n    followup: (text: string, images?: string[]) => {\n      // 无图走同步快路径（与历史行为一致）；有图先经 attachments 持久化再投递。\n      if (images === undefined || images.length === 0) {\n        agent.followup(toUserMessageSync(text))\n        return Promise.resolve()\n      }\n      return toUserMessage(agent.ctx, text, images).then((message) => {\n        agent.followup(message)\n      })\n    },\n    steer: (text: string) =>{  agent.steer(toUserMessageSync(text)) },\n    inject: (text: string) =>{  agent.inject(toUserMessageSync(text)) },\n    cancel: (cause: AgentCancelCause, options?: CancelOptions) => {\n      if (options === undefined) agent.cancel(cause)\n      else agent.cancel(cause, options)\n    },\n    whenIdle: () => agent.whenIdle(),\n  }\n}\n\n/**\n * Resolve controls for a live agent by session id through the registry, for\n * session switching. The returned surface drives the bare agent and never\n * disposes it (non-owner semantics).\n * @param ctx - any context exposing `ctx.agents`.\n * @param id - the shared agent/session id to look up.\n * @returns controls for the live agent, or `undefined` when none is registered.\n */\nexport function controlsFromRegistry(ctx: Context, id: SessionId): AgentControls | undefined {\n  const agent = ctx.agents.get(id)\n  return agent === undefined ? undefined : controlsFromAgent(agent)\n}\n"
    },
    {
      "path": "src/controllers/approval-controller.ts",
      "content": "/**\n * ApprovalController — 待审批挂起状态机（Wave 1 从 ui/app.ts 提取）。\n *\n * 持有 pendingApproval 挂起态（req + resolve 句柄）与 alwaysApprove 短路标志。\n * handle() 是 approval/request 订阅的 answerer 入口，语义与 user-approval\n * waterfall 对齐：\n * - alwaysApprove 且当前会话 → 短路放行 allowed-once（不挂起、不消费）。\n * - 工具/命令前缀会话白名单（t/p 键）命中且当前会话 → 同样短路放行。\n * - 非当前会话或已有挂起 → 委托 next()（fail-closed：TUI 一次只呈现一个确认，\n *   apiproxy 等链上 answerer 处理远端转发）。\n * - 当前会话无挂起 → 挂起，返回等用户 y/N 的 promise。\n *\n * 决策分层（阶段 2）新增两件本地态：\n * - allowedPrefixes：bash 类工具的命令前缀白名单（p 键「此命令前缀不再问」），\n *   前缀由注入的 getCommandPrefix 在 handle() 时一次性提取缓存（transcript\n *   查找 + JSON 解析不随渲染重复）。协议层只有 allowed-once，前缀记忆是纯\n *   TUI 本地态短路（与 allowedTools 同型）。\n * - feedback：拒绝反馈输入态（f 键进入，复刻 question-controller 范式）；\n *   settle 时复位。反馈文本的 steer 旁路投递由 app 侧组装，controller 不碰。\n *\n * 会话归属经 getCurrentSessionId() getter 注入（app.ts 持有 activeSessionId），\n * 渲染经 peek() 快照消费；不 import app.ts、不碰渲染。\n *\n * 超时由 controller 内建承担（ApprovalPeek.since 仅为信息性字段，渲染侧\n * 不负责超时判定）：挂起超过 timeoutMs 无人应答 → fail-closed 自动结算\n * cancelled，卡片不会无限挂起。\n *\n * @module @deepseek-ai/dsh-tianshu-tui/controllers/approval-controller\n */\n\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport type { ToolCallId } from '@deepseek-ai/dsh-llm'\n\n/** 审批 answerer 的本地请求形状（与 user-approval 词汇对齐；字段子集——TUI 只需展示所需）。 */\nexport interface PendingApprovalRequest {\n  agent: { session: { id: SessionId } }\n  toolName: string\n  reason?: string\n  /** C2 项 1：关联的精确工具调用（user-approval 运行时携带，用于审批 diff 查找）。 */\n  callId?: ToolCallId\n  /**\n   * 请求撤销信号（user-approval `ApprovalRequest.signal` 透传）：abort 时挂起\n   * 自动结算为 cancelled——asker 侧已把 abort 竞速为 cancelled，卡片必须同步\n   * 消失，否则用户按 y 见卡片消失实际被拒且无提示（UI/outcome 不一致）。\n   */\n  signal?: AbortSignal\n}\n\n/** 用户决定（与 user-approval ApprovalOutcome 对齐）。 */\nexport type ApprovalOutcome = 'allowed-once' | 'rejected' | 'cancelled' | 'unavailable'\n\n/** 挂起态快照（renderLive 消费；无挂起时 peek() 返回 null）。 */\nexport interface ApprovalPeek {\n  /** 待决审批请求。 */\n  req: PendingApprovalRequest\n  /** 挂起时间戳（ms；信息性字段——超时判定由 controller 内建 timeoutMs 承担，渲染侧不读）。 */\n  since: number\n  /** 拒绝反馈输入态（f 键进入；结算时复位；渲染侧据此显示反馈提示行）。 */\n  feedbackMode: boolean\n}\n\n/** 审批挂起默认超时（ms）：挂起超过即 fail-closed 自动结算 cancelled（可经 options.timeoutMs 覆盖）。 */\nexport const DEFAULT_APPROVAL_TIMEOUT_MS = 60_000\n\n/** ApprovalController 的依赖注入（当前会话读取、状态变化回调）。 */\nexport interface ApprovalControllerOptions {\n  /** 当前会话 id 读取函数（app.ts 注入 activeSessionId；null = 尚未 attach）。 */\n  getCurrentSessionId: () => SessionId | null\n  /** 状态实际变化（挂起/结算）后回调（app 侧触发重绘）。 */\n  onChanged?: () => void\n  /** 挂起超时毫秒数（超过即自动结算 cancelled，fail-closed；缺省 DEFAULT_APPROVAL_TIMEOUT_MS）。 */\n  timeoutMs?: number\n  /**\n   * 命令前缀提取（p 键「此命令前缀不再问」数据源）：app 侧注入\n   * callId → transcript → command 首 token；非 bash 类工具/提取失败返回 null。\n   * handle() 时一次性调用并缓存进挂起态（前缀白名单短路 + p 键守卫共用）。\n   */\n  getCommandPrefix?: (req: PendingApprovalRequest) => string | null\n}\n\n/**\n * 待审批挂起状态机：handle() 按短路放行 / next() 委托 / 挂起三选一，\n * settle() 结算用户决定，peek() 给 renderLive 出快照（见模块注释语义）。\n * 挂起超过 timeoutMs 无人应答时自动结算 cancelled（fail-closed）。\n */\nexport class ApprovalController {\n  private pending: {\n    req: PendingApprovalRequest\n    resolve: (outcome: ApprovalOutcome) => void\n    since: number\n    /** handle() 时一次性提取的命令前缀（p 键守卫/投影读取；非 bash 类 null）。 */\n    prefix: string | null\n    /** 挂起时注册的 abort 监听（settle 时移除，防泄漏/防二次结算）。 */\n    onAbort?: () => void\n    /** 挂起超时 timer（settle 时清除，防二次结算）。 */\n    timer: ReturnType<typeof setTimeout> | undefined\n  } | null = null\n  private alwaysApproveFlag = false\n  /**\n   * 会话级工具白名单（任务4a，2026-08-27）：`t` 键「本会话允许此工具」加入，\n   * 命中请求短路放行——其他工具仍逐卡审批（与 alwaysApprove 的全放行互补）。\n   * 会话切换时 app 侧调 clearSessionGrants() 复位（跨会话残留清理节）。\n   */\n  private readonly allowedTools = new Set<string>()\n  /**\n   * 会话级命令前缀白名单（决策分层阶段 2）：`p` 键「此命令前缀不再问」加入，\n   * bash 类工具后续同前缀请求短路放行——比 t 键整工具放行再收敛一档。\n   */\n  private readonly allowedPrefixes = new Set<string>()\n  /** 拒绝反馈输入态（f 键进入；settle 复位——复刻 question-controller 范式）。 */\n  private feedback = false\n  private readonly getCurrentSessionId: () => SessionId | null\n  private readonly onChanged: (() => void) | undefined\n  private readonly timeoutMs: number\n  private readonly getCommandPrefix: ((req: PendingApprovalRequest) => string | null) | undefined\n\n  constructor(options: ApprovalControllerOptions) {\n    this.getCurrentSessionId = options.getCurrentSessionId\n    this.onChanged = options.onChanged\n    this.timeoutMs = options.timeoutMs ?? DEFAULT_APPROVAL_TIMEOUT_MS\n    this.getCommandPrefix = options.getCommandPrefix\n  }\n\n  /** 是否有挂起的审批（handleKey 分支入口判断）。 */\n  get isPending(): boolean {\n    return this.pending !== null\n  }\n\n  /** C3 项 4：always-approve 模式激活标志（三态循环读写；退出/切会话时 app 侧复位）。 */\n  get alwaysApprove(): boolean {\n    return this.alwaysApproveFlag\n  }\n\n  /**\n   * 设置 always-approve 模式（C3 项 4 三态循环；statusLine 徽标由 app 侧同步）。\n   * @param flag - true 时当前会话的审批请求短路放行。\n   */\n  setAlwaysApprove(flag: boolean): void {\n    this.alwaysApproveFlag = flag\n  }\n\n  /** 会话级工具白名单只读视图（渲染/调试用）。 */\n  get allowedToolNames(): readonly string[] {\n    return [...this.allowedTools]\n  }\n\n  /** 白名单是否命中该工具（handleKey 决定键位提示可省；短路判定以 handle 为准）。 */\n  isToolAllowed(toolName: string): boolean {\n    return this.allowedTools.has(toolName)\n  }\n\n  /** 把工具加入会话白名单（`t` 键；该工具后续请求自动放行）。 */\n  allowTool(toolName: string): void {\n    this.allowedTools.add(toolName)\n  }\n\n  /** 命令前缀是否已加白（调试/测试用；短路判定以 handle 为准）。 */\n  isPrefixAllowed(prefix: string): boolean {\n    return this.allowedPrefixes.has(prefix)\n  }\n\n  /** 把命令前缀加入会话白名单（`p` 键；bash 类同前缀请求后续自动放行）。 */\n  allowCommandPrefix(prefix: string): void {\n    this.allowedPrefixes.add(prefix)\n  }\n\n  /**\n   * 清空会话级授权（工具白名单 + 命令前缀白名单；会话切换时 app 侧复位——\n   * 白名单语义限于单个会话）。\n   */\n  clearSessionGrants(): void {\n    this.allowedTools.clear()\n    this.allowedPrefixes.clear()\n  }\n\n  /** 挂起请求的命令前缀（handle 时提取缓存；无挂起/非 bash 类 null）。 */\n  get pendingCommandPrefix(): string | null {\n    return this.pending?.prefix ?? null\n  }\n\n  /** 拒绝反馈输入态（f 键进入；结算时复位）。 */\n  get feedbackMode(): boolean {\n    return this.feedback\n  }\n\n  /**\n   * 进入/退出拒绝反馈输入态（f 键 / Esc 返回选项态；不触发结算）。\n   * @param flag - true 进入反馈输入态，false 返回选项态。\n   */\n  setFeedbackMode(flag: boolean): void {\n    this.feedback = flag\n  }\n\n  /**\n   * `t` 键复合操作：挂起请求的工具入会话白名单并结算 allowed-once。\n   * @returns false = 无挂起（未结算）。\n   */\n  approveWithTool(): boolean {\n    const pending = this.pending\n    if (pending === null) return false\n    this.allowTool(pending.req.toolName)\n    this.settle('allowed-once')\n    return true\n  }\n\n  /**\n   * `p` 键复合操作：挂起请求的命令前缀入会话白名单并结算 allowed-once。\n   * @returns false = 无挂起或无前缀可提（未结算）。\n   */\n  approveWithPrefix(): boolean {\n    const prefix = this.pendingCommandPrefix\n    if (prefix === null) return false\n    this.allowCommandPrefix(prefix)\n    this.settle('allowed-once')\n    return true\n  }\n\n  /**\n   * 审批 answerer 入口：短路放行 / 委托 next() / 挂起，三选一。\n   * @param req - 待决审批请求（approval/request 事件 payload）。\n   * @param next - waterfall 委托（不处理时调用；链上其他 answerer 兜底）。\n   * @returns 用户决定（allowed-once/rejected/cancelled）或 next() 结果。\n   */\n  handle(req: PendingApprovalRequest, next: () => Promise<ApprovalOutcome>): Promise<ApprovalOutcome> {\n    const current = this.getCurrentSessionId()\n    // C3 项 4：always-approve 短路放行（不挂起提示，不消费 pendingApproval）。\n    // 仅限当前会话：非当前会话的请求必须 next() 委托（apiproxy 等链上 answerer），\n    // 否则 TUI 会截胡远端转发的审批。\n    if (this.alwaysApproveFlag && req.agent.session.id === current) {\n      return Promise.resolve('allowed-once')\n    }\n    // 任务4a：工具级会话白名单短路——`t` 键加过的工具自动放行，其他工具仍\n    // 逐卡审批。作用域与 always-approve 相同（仅当前会话）。\n    if (this.allowedTools.has(req.toolName) && req.agent.session.id === current) {\n      return Promise.resolve('allowed-once')\n    }\n    // 决策分层阶段 2：命令前缀会话白名单短路——`p` 键加过的前缀自动放行。\n    // 前缀在此一次性提取（transcript 查找 + JSON 解析），挂起后缓存复用。\n    const prefix = req.agent.session.id === current\n      ? this.getCommandPrefix?.(req) ?? null\n      : null\n    if (prefix !== null && this.allowedPrefixes.has(prefix)) {\n      return Promise.resolve('allowed-once')\n    }\n    if (req.agent.session.id !== current || this.pending !== null) {\n      return next()\n    }\n    return new Promise<ApprovalOutcome>((resolve) => {\n      const signal = req.signal\n      // 已撤销的请求不呈现、不挂起：asker 侧已把 abort 竞速为 cancelled，\n      // 挂起只会让卡片滞留（UI/outcome 不一致）——直接 fail-closed 结算。\n      if (signal !== undefined && signal.aborted) {\n        resolve('cancelled')\n        return\n      }\n      const onAbort = (): void => { this.settle('cancelled') }\n      // 挂起超时：超过 timeoutMs 无人应答 → fail-closed 自动结算 cancelled，\n      // 卡片不无限挂起（settle 时清除 timer，防用户结算后二次结算）。\n      // 有限值守卫：Node setTimeout 对 > 2^31-1 ms 的值溢出为 1ms 立即触发。\n      const timer = Number.isFinite(this.timeoutMs)\n        ? setTimeout(() => { this.settle('cancelled') }, this.timeoutMs)\n        : undefined\n      this.pending = {\n        req,\n        resolve,\n        since: Date.now(),\n        prefix,\n        timer,\n        ...(signal !== undefined ? { onAbort } : {}),\n      }\n      // 挂起时监听请求撤销：agent 取消（abort）→ 自动结算 cancelled，\n      // 与 asker 拿到的 cancelled 对齐，卡片经 onChanged 同步消失。\n      signal?.addEventListener('abort', onAbort, { once: true })\n      this.onChanged?.()\n    })\n  }\n\n  /**\n   * 结算挂起的审批请求（用户按键 y/N/Ctrl+C；会话卸载时 cancel 为 cancelled；\n   * 请求 signal abort 时自动结算为 cancelled；挂起超过 timeoutMs 时自动结算为 cancelled）。\n   * @param outcome - 用户决定。\n   */\n  settle(outcome: ApprovalOutcome): void {\n    const pending = this.pending\n    /* v8 ignore next -- settle 仅在 pendingApproval 非 null 的调用点可达 */\n    if (pending === null) return\n    this.pending = null\n    // 拒绝反馈输入态随结算复位（与 question-controller settle 复位 feedback 同型）。\n    this.feedback = false\n    // 清除挂起超时 timer：已结算后不得再被超时二次结算\n    // （timer 已触发时 clearTimeout 是 no-op，安全）。\n    if (pending.timer !== undefined) {\n      clearTimeout(pending.timer)\n    }\n    // 移除挂起时注册的 abort 监听：用户已结算后 agent 再取消不得二次结算\n    // （once 语义由 settle 侧保证，而非依赖 { once: true } 的时序）。\n    const onAbort = pending.onAbort\n    if (onAbort !== undefined) {\n      pending.req.signal?.removeEventListener('abort', onAbort)\n    }\n    pending.resolve(outcome)\n    this.onChanged?.()\n  }\n\n  /**\n   * 当前挂起态快照（renderLive 审批段消费）。\n   * @returns { req, since, feedbackMode }；无挂起 null。\n   */\n  peek(): ApprovalPeek | null {\n    if (this.pending === null) return null\n    return { req: this.pending.req, since: this.pending.since, feedbackMode: this.feedback }\n  }\n}\n"
    },
    {
      "path": "src/engine/live-engine.ts",
      "content": "/**\n * T9 LiveEngine — 管理终端底部动态区域（live region）的增量重绘。\n *\n * 核心机制：\n * - 在渲染 live region 之前，用 `cursor save` 保存滚动位置。\n * - 渲染时：上移到 live region 起始行 → 逐行擦除 + 重写 → 恢复光标。\n * - live region 永远只占底部 N 行（通常 5-20 行），远小于终端高度。\n * - streaming 内容由 BlockStreamWriter 控制，超出的部分已经 commit 到 scrollback。\n *\n * **Display-row awareness**: 所有行数追踪使用 visual display rows（wrapping-aware），\n * 而非 logical line count。一个 200 字符的行在 80 列终端占 3 display rows。\n * cursorUp / erase / lastDisplayRows 全部基于 display rows，防止 wrap 行导致\n * cursor 定位偏差 → ghost 行 / 重复渲染。\n *\n * 与 Ink 的区别：\n * - Ink 在 live region >= terminal rows 时执行 `\\x1B[2J` 全屏清屏，\n *   LiveEngine 永远不会触发全屏清屏——live region 被严格限制在底部。\n */\n\nimport type { WriteStream } from 'node:tty'\nimport { ANSI, cursorUp, cursorDown, cursorToCol } from './ansi.js'\nimport { displayWidth, ambiguousWideEnabled } from '../width.js'\n\n/** live region 的一行（单逻辑行契约；嵌入换行会被 normalizeLines 兜底展开）。 */\nexport interface LiveRegionLine {\n  /** 该行的 ANSI 格式化文本（包含颜色码） */\n  text: string\n  /** 可选：截断指示符 */\n  truncated?: boolean\n  /**\n   * 可选：输入框软件光标（█）左侧的 0-based cell 列（2026-07-23 IME 锚定）。\n   * 终端 IME 候选窗锚定【硬件光标】而非自绘 █——帧末把硬件光标搬到该行该列，\n   * 组词串才会出现在输入框内（kimi-code pi-tui 同款机制，结构字段替代其零宽\n   * APC marker：不污染文本、不干扰 displayWidth 行数计量）。normalize/rowBudget\n   * 均 {...l} 透传该字段。\n   */\n  caretCol?: number\n}\n\n/** LiveEngine 构造参数。 */\nexport interface LiveEngineOptions {\n  stdout: WriteStream\n  /** 预留行数（输入行等需要始终可见的行） */\n  reservedRows?: number\n  /** 最大 live region 行数（安全上限，防止意外超屏） */\n  maxRows?: number\n  /**\n   * CPR 探针请求回调（通常写 `\\x1B[6n` 到 stdout）。响应经 stdin 回到\n   * InputHandler，再喂给 {@link LiveEngine.noteCpr}。提供后启用外来写入检测。\n   */\n  onProbeRequest?: () => void\n  /** 检测到 live region 被外来写入污染（光标偏离驻停点）时回调——调用方应重渲染。 */\n  onPolluted?: () => void\n}\n\nexport {\n  LIVE_TOOL_CARD_MAX,\n  assembleIdleKey,\n  liveHasSpinner,\n  liveIdleKey,\n  liveMaxRowsFor,\n  nextDynamicBudget,\n  padDynamicRegion,\n  shouldSkipIdleAssemble,\n  workingRowsCap,\n} from './live-budget.js'\nexport type { LiveIdleSources, PadDynamicRegionOptions } from './live-budget.js'\n\n/**\n * 终端底部动态区域（live region）的增量重绘引擎。\n * 行数追踪全部基于 wrapping-aware display rows；渲染后光标常驻区域末行\n * （cursor-resident 协议），并以 CPR 探针自愈外来写入污染。\n */\nexport class LiveEngine {\n  private stdout: WriteStream\n  private maxRows: number\n\n  /** 上一帧渲染的 display rows（wrapping-aware）。用于计算上移量。 */\n  private lastDisplayRows = 0\n  /** lineCache 渲染时的终端宽度。resize 检测：宽度变了说明屏上内容已被 reflow。 */\n  private lastColumns = 0\n  /** 是否已执行过首次渲染（用于判断是否需要 save cursor） */\n  private hasRendered = false\n  /** live region 行缓存：每行的原始文本（不含 ANSI）用于 diff */\n  private lineCache: string[] = []\n\n  /**\n   * ambiguous 宽度模式缓存。`ambiguousWideEnabled()` 每次读 `process.env` 并做\n   * 字符串比较，而一帧渲染里 rowsForLine 被调数十次（countDisplayRows / canDiff /\n   * buildDiff / reconcileWidth），重复读 env 是无谓开销。该值在一次进程中基本不变，\n   * 惰性读取一次后缓存即可。\n   */\n  private ambiguousWideCache: boolean | null = null\n\n  // ── CPR 自愈状态 ──────────────────────────────────────────────\n  // 渲染后光标应驻停在 live region 末行末尾。任何外来写入（其他进程写共享\n  // TTY、stderr 直写）会移动光标并撑高屏上区域，使 lastDisplayRows 失同步——\n  // 之后 cursorUp 回顶量不足，旧帧顶部残留进 scrollback（叠屏/重复帧）。\n  // 机制：渲染后（节流）发 CPR 探针记录驻停基线；后续探针响应偏离基线即判污染，\n  // 经 onPolluted 通知调用方重渲染，render 开头走恢复路径重锚。\n  private onProbeRequest?: () => void\n  private onPolluted?: () => void\n  /** 最近一次确认的驻停位置（CPR 响应，1-based）。null = 未建立基线。 */\n  private cprBaseline: { row: number; col: number } | null = null\n  /** 已发出探针但未收到响应（带超时自愈，防终端不应答导致探针停摆）。 */\n  private cprProbePending = false\n  private lastCprProbeMs = 0\n  /** 污染标记：下一帧 render 跳过 H2 短路/diff，走恢复重铺。 */\n  private polluted = false\n  /** 最近一次探针响应的光标行（恢复路径的爬升上限——绝不爬出视口顶）。 */\n  private cprReportRow = 1\n\n  // ── 硬件光标驻停（2026-07-23 IME 锚定；2026-07-24 默认重开）─────────\n  // 帧末把（默认隐藏的）硬件光标搬到输入框软件光标 █ 的坐标——终端 IME 候选窗\n  // 锚定硬件光标，自绘 █ 它不可见。kimi-code pi-tui 同款机制（tui.ts\n  // positionHardwareCursor），适配本引擎 cursor-resident 协议：\n  // - parkedRowsUp：驻停点距区域末行的 display rows（无 caret 帧 = 0）。帧首\n  //   爬升量必须减去它（光标不在末行尾而在 caret 行）。\n  // - parkedCol：驻停放列（0-based cell）；null = 驻停末行尾（历史协议）。\n  // - 默认驻停但保持隐藏（单指针视觉）；RIVET_TUI_HARDWARE_CURSOR=1 仅控制\n  //   可见性（个别终端光标可见才跟踪 IME）。\n  // - CPR 防误判：响应按 probeParked（发针时 rowsUp）折算区域末行；若响应\n  //   到达时 rowsUp 已漂移（slash 面板开合等合法几何变化）→ 丢弃本次判定\n  //   （2026-07-24 重复行根修——dc572683 曾整体关闭 parking 兜底，此为正修）。\n  private parkedRowsUp = 0\n  private parkedCol: number | null = null\n  /** 发 CPR 探针那一刻的驻停记账——响应按它折算区域末行，防 caret 移动误判污染。 */\n  private probeParked: { rowsUp: number; col: number | null } | null = null\n  private readonly hardwareCursorVisible = process.env.RIVET_TUI_HARDWARE_CURSOR === '1'\n\n  /** 探针最小间隔：渲染每帧都可能触发，防探针风暴。 */\n  private static readonly CPR_PROBE_MIN_INTERVAL_MS = 1000\n  /** 探针响应超时：超过即允许重发（兼容不应答 DSR 的环境）。 */\n  private static readonly CPR_PROBE_TIMEOUT_MS = 5000\n\n  /** ambiguous 宽度模式（缓存 process.env 读取）。 */\n  private ambiguousWide(): boolean {\n    if (this.ambiguousWideCache === null) {\n      this.ambiguousWideCache = ambiguousWideEnabled()\n    }\n    return this.ambiguousWideCache\n  }\n\n  constructor(options: LiveEngineOptions) {\n    this.stdout = options.stdout\n    this.maxRows = options.maxRows ?? 20\n    if (options.onProbeRequest !== undefined) this.onProbeRequest = options.onProbeRequest\n    if (options.onPolluted !== undefined) this.onPolluted = options.onPolluted\n  }\n\n  // ── CPR 自愈 ──────────────────────────────────────────────────\n\n  /**\n   * 暂停 CPR 污染检测，并禁止 render/clear 写 stdout。\n   * overlay（picker/pager 等）激活期间光标在 alt screen，CPR 响应的位置不代表\n   * 主屏 live region；若照常比对会误判污染并触发 renderLive 把主屏帧写进 alt\n   * screen（picker 残影泄漏回主会话的根因）。即便上层漏跳过 renderLive，引擎\n   * 层也不得改写 alt screen，且不得把主屏 lastDisplayRows 清零（否则退出后\n   * 会当空区再 append 一份 live 区）。\n   * 调用方应在 overlay 激活时 suppress，退出时 resume（并作废基线等下一帧重建）。\n   */\n  private probeSuppressed = false\n\n  /** overlay 激活：暂停探针发送与污染判定，render/clear 不再写屏。 */\n  suppressProbe(): void {\n    this.probeSuppressed = true\n    this.cprProbePending = false\n    this.cprBaseline = null\n  }\n\n  /** overlay 退出：恢复检测；基线作废，下一帧/探针重新建立，避免跨 alt screen 误判。 */\n  resumeProbe(): void {\n    this.probeSuppressed = false\n    this.cprBaseline = null\n  }\n\n  /**\n   * 请求发一次 CPR 探针（受节流与 pending 去重；无 onProbeRequest 时 no-op）。\n   * 调用点：render 结束（帧后驻停基线）+ 空闲期定时器（检出 idle 污染）。\n   * overlay 激活期间不发（见 suppressProbe）。\n   */\n  requestProbe(): void {\n    if (this.probeSuppressed) return\n    if (!this.onProbeRequest) return\n    const now = Date.now()\n    if (this.cprProbePending && now - this.lastCprProbeMs < LiveEngine.CPR_PROBE_TIMEOUT_MS) return\n    if (!this.cprProbePending && now - this.lastCprProbeMs < LiveEngine.CPR_PROBE_MIN_INTERVAL_MS) return\n    this.cprProbePending = true\n    this.lastCprProbeMs = now\n    // 记录发探针瞬间的驻停位置——noteCpr 按它把响应折算回区域末行再判污染。\n    this.probeParked = { rowsUp: this.parkedRowsUp, col: this.parkedCol }\n    this.onProbeRequest()\n  }\n\n  /**\n   * 喂入一条 CPR 响应（row/col 1-based，来自 InputHandler 的 onCpr）。\n   * 首个响应建立驻停基线；后续响应与基线比对——偏离说明光标被外来写入移动，\n   * 标记污染并回调 onPolluted（由调用方触发重渲染走恢复路径）。\n   * @param row - 光标行（1-based）\n   * @param col - 光标列（1-based）\n   */\n  noteCpr(row: number, col: number): void {\n    this.cprProbePending = false\n    // overlay 激活期间（alt screen）：光标位置不代表主屏 live region，\n    // 不判污染也不更新基线，避免退出后用跨 alt screen 的基线误判。\n    if (this.probeSuppressed) return\n    this.cprReportRow = row\n    const probe = this.probeParked\n    // rowsUp 漂移丢弃（2026-07-24 重复行根修）：发针后几何合法变化（slash\n    // 面板开合/输入框增行）使 caret 之下行数改变，响应无法可靠折算区域末行\n    // ——既不判污染也不动基线（误判断曾触发恢复性全量重铺 = 输入框重复行）。\n    // rowsUp 稳定时按 FIFO 语义用发针时记账折算，判定与基线照常。\n    if (probe && probe.rowsUp !== this.parkedRowsUp) return\n    // caret 驻停期间响应的是 caret 坐标：折算回区域末行再与基线比对\n    //（发探针时的 parkedRowsUp 记账）；列比对只在驻停末行尾时进行——\n    // caret 驻停下列随打字合法变化，比列会误报。\n    const regionEndRow = row + (probe?.rowsUp ?? 0)\n    const compareCol = probe?.col == null\n    // 区域未在屏上（clear/commit 途中）时只更新基线，不判污染。\n    if (!this.hasRendered || this.lastDisplayRows === 0) {\n      this.cprBaseline = { row: regionEndRow, col }\n      return\n    }\n    if (!this.cprBaseline) {\n      this.cprBaseline = { row: regionEndRow, col }\n      return\n    }\n    if (this.cprBaseline.row !== regionEndRow || (compareCol && this.cprBaseline.col !== col)) {\n      this.polluted = true\n      // 立即采纳新位置为基线：迟到的响应（渲染/commit 交错）不会造成持续误判。\n      this.cprBaseline = { row: regionEndRow, col }\n      this.onPolluted?.()\n      return\n    }\n    this.cprBaseline = { row: regionEndRow, col }\n  }\n\n  /**\n   * 更新 live region 行上限（终端 resize 时调用）。\n   * maxRows 若大于终端高度，全量重写的 cursorUp 回顶量会超出屏幕导致错位，\n   * 因此调用方应传入高度感知的值（如 `min(28, rows - 1)`）。\n   * @param n - 新行上限；非正/非整数值被钳到 ≥1 的整数\n   */\n  setMaxRows(n: number): void {\n    this.maxRows = Math.max(1, Math.floor(n))\n  }\n\n  // ── Display-row helpers ───────────────────────────────────────\n\n  /** 单个 logical line 占用的 display rows（wrapping-aware）。 */\n  private rowsForLine(text: string): number {\n    const width = this.stdout.columns || 80\n    if (width <= 0) return 1\n    // 行数估算必须与终端实际换行一致：CJK 终端把 ambiguous 符号按 2 列渲染，\n    // 用 ambiguousAsWide 度量（env 门控，默认 narrow=string-width）避免低估行数。\n    const dw = displayWidth(text, { ambiguousAsWide: this.ambiguousWide() })\n    if (dw === 0) return 1\n    return Math.ceil(dw / width)\n  }\n\n  /** 一组 LiveRegionLine 占用的总 display rows。 */\n  private countDisplayRows(lines: readonly LiveRegionLine[]): number {\n    let total = 0\n    for (const line of lines) {\n      total += this.rowsForLine(line.text)\n    }\n    return total\n  }\n\n  /**\n   * 输入行归一化（2026-07-21 输入框重影修复）。\n   *\n   * LiveRegionLine 的契约是「单逻辑行」，但上游内容偶发携带嵌入换行——已证实的\n   * 泄漏链：worker 多行 summary（review 门 evidence 用 `\\n` 拼接）→\n   * `progressLine: summary.slice(0, 80)` → FleetRegistry.activity → 舰队面板活动行。\n   * 带 `\\n` 的行在屏上占多个显示行，而 rowsForLine 基于 displayWidth\n   * （string-width 剥控制符，`\\n` 计 0 宽）按 1 行计 → lastDisplayRows 低于屏上\n   * 实际行数 → 下一帧 cursorUp 回顶不足 → 旧帧顶部（输入框头行+边框）残留进\n   * scrollback，正是「输入框重影叠屏」的形态。\n   *\n   * 处理：`\\n` 展开为独立行；`\\r`/`\\t` 替换为空格（同样是 string-width 计 0 宽\n   * 但终端会移动光标/跳列的字符）。内容侧净化（progressSnippet）是第一道防线，\n   * 这里是引擎层兜底——任何未来新增的内容路径都不能再破坏行数追踪。\n   */\n  private normalizeLines(lines: readonly LiveRegionLine[]): readonly LiveRegionLine[] {\n    let dirty = false\n    for (const l of lines) {\n      if (l.text.includes('\\n') || l.text.includes('\\r') || l.text.includes('\\t')) {\n        dirty = true\n        break\n      }\n    }\n    if (!dirty) return lines\n    const out: LiveRegionLine[] = []\n    for (const l of lines) {\n      const cleaned = l.text.replace(/[\\r\\t]/g, ' ')\n      if (!cleaned.includes('\\n')) {\n        out.push(cleaned === l.text ? l : { ...l, text: cleaned })\n        continue\n      }\n      for (const seg of cleaned.split('\\n')) {\n        out.push({ ...l, text: seg })\n      }\n    }\n    return out\n  }\n\n  // ── Render ────────────────────────────────────────────────────\n\n  /**\n   * resize 协调：终端宽度变化时，已绘制的 live region 内容会被终端按新宽 reflow，\n   * 其占用的 display rows 随之改变。但 `lastDisplayRows` 是上一帧在**旧宽度**下数的，\n   * 若直接用于 `moveToTop`，cursorUp 量与屏上实际行数不符 → 回顶欠/过 → 旧帧顶部\n   * 残留进 scrollback（多份不同宽度的 chrome/面板叠屏，见 resize 回归测试）。\n   *\n   * 修复：检测到宽度变化时，按**当前宽度**从 `lineCache` 重算 `lastDisplayRows`，\n   * 使其与终端 reflow 后的屏上行数一致，再做相对回顶。\n   */\n  private reconcileWidth(): void {\n    const currentColumns = this.stdout.columns || 80\n    if (this.hasRendered && this.lastDisplayRows > 0 && currentColumns !== this.lastColumns) {\n      this.lastDisplayRows = this.countDisplayRows(this.lineCache.map(text => ({ text })))\n    }\n    this.lastColumns = currentColumns\n  }\n\n  /**\n   * 渲染 live region（cursor-resident 协议，对标 aider mdstream / ink createIncremental）。\n   *\n   * 核心不变量：\n   * - 渲染后光标**常驻 live region 最后一行末尾**（尾行不写 `\\n`）。\n   *   这避免了在终端底部因尾行换行触发滚屏 → 杜绝\"贴底每帧滚动\"的卡顿。\n   * - 增量重绘用**相对光标移动**（cursorUp/cursorDown）回到区域顶，不使用\n   *   SAVE/RESTORE 绝对光标——内容滚动后绝对坐标会失效错位。\n   * - **行级 diff**：结构未变（行数 + 单显示行）时只重写变化的行，跳过未变行（少闪）。\n   * - 整帧用 CSI 2026 同步输出包裹，原子刷新防撕裂。\n   *\n   * @param lines - 要显示的行（含 ANSI 格式化）\n   * @param opts - reservedTail：超预算截断时恒保留的尾部行数（chrome 保护）\n   */\n  render(lines: readonly LiveRegionLine[], opts?: { reservedTail?: number }): void {\n    // alt screen 期间主屏 live 区是冻结快照：不写 stdout，也不更新几何。\n    if (this.probeSuppressed) return\n    const bounded = this.applyRowBudget(this.normalizeLines(lines), opts?.reservedTail)\n    const parking = this.computeParking(bounded)\n\n    // 恢复重铺：CPR 检出外来写入污染后，不再信任 lastDisplayRows 的屏上假设\n    // （H2 短路会被 lineCache 与屏上不符的内容欺骗，diff 会加剧错位）。\n    // 爬升量以「追踪行数」与「最近 CPR 报告行」双封顶——绝不爬出视口顶。\n    // 外来行撑高区域的行数不可知，顶部残留 ≤δ 行无法避免（相对寻址的固有限制），\n    // 但外来文本被擦除、帧重新锚定，后续帧恢复一致。\n    if (this.polluted) {\n      this.polluted = false\n      // resize 与污染判定常并发（reflow 移动光标即触发）：爬升前先按当前宽度从\n      // lineCache 重算屏上行数。否则 lastDisplayRows 仍是旧宽度计数，变窄 reflow\n      // 把区域撑高后爬升不足，旧帧顶部残留进 scrollback（resize 输入框叠屏）。\n      this.reconcileWidth()\n      const newDisplayRows = this.countDisplayRows(bounded)\n      let body: string\n      if (this.hasRendered && this.lastDisplayRows > 0) {\n        const climb = Math.min(Math.max(0, this.lastDisplayRows - 1 - this.parkedRowsUp), Math.max(0, this.cprReportRow - 1))\n        body = (climb > 0 ? cursorUp(climb) : '') + '\\r' + ANSI.ERASE_SCREEN_END + this.buildAppend(bounded)\n      } else {\n        body = this.buildAppend(bounded)\n      }\n      this.stdout.write(ANSI.BEGIN_SYNC + ANSI.HIDE_CURSOR + body + this.buildParkSeq(parking) + ANSI.END_SYNC)\n      this.lastDisplayRows = newDisplayRows\n      this.lineCache = bounded.map(l => l.text)\n      this.hasRendered = true\n      this.lastColumns = this.stdout.columns || 80\n      this.cprBaseline = null // 重锚完成，帧后探针重建基线\n      this.setParked(parking)\n      this.requestProbe()\n      return\n    }\n\n    // H2 无变化短路：屏上 live region 内容与本帧逐行完全一致且终端宽度未变 →\n    // 无需任何重绘（省去 diff 计算与 stdout 写入）。idle / ticker 空转的主要省功点。\n    // 用 lineCache（屏上真实内容的权威记录）比对，天然兼容 clear/reset/overlay 退出：\n    // 那些路径会令 lastDisplayRows===0 或 hasRendered===false，不会被误短路。\n    const currentColumns = this.stdout.columns || 80\n    if (\n      this.hasRendered &&\n      this.lastDisplayRows > 0 &&\n      currentColumns === this.lastColumns &&\n      bounded.length === this.lineCache.length &&\n      bounded.every((l, i) => l.text === this.lineCache[i])\n    ) {\n      // 行未变但 caret 移动（纯光标键）：不重绘文字，只把硬件光标搬到新坐标\n      // （kimi-code pi-tui 同款——无变化帧也归位光标，几字节零闪烁）。\n      // caret 消失（parking=null）的转移走常规路径收敛，不在此处理。\n      if (parking) this.reparkIfChanged(parking)\n      return\n    }\n\n    // resize 检测必须在 reconcileWidth 覆盖 lastColumns 之前取值。\n    const widthChanged = this.hasRendered && this.lastDisplayRows > 0 && currentColumns !== this.lastColumns\n\n    this.reconcileWidth()\n    const newDisplayRows = this.countDisplayRows(bounded)\n\n    // 首次渲染 或 clear/clearForCommit 之后（lastDisplayRows === 0）：\n    // 直接在当前位置 append 输出。尾行不带 `\\n`，光标停在最后一行末尾。\n    if (!this.hasRendered || this.lastDisplayRows === 0) {\n      // 首帧 / clear/overlay 退出后的全量重铺同样用 CSI 2026 包裹，原子刷新\n      // 防撕裂（与增量帧一致）。尾行不带 `\\n`，光标仍常驻最后一行末尾。\n      // 同步隐藏硬件光标，避免 overlay 退出后主屏出现额外闪烁指针。\n      this.stdout.write(ANSI.BEGIN_SYNC + ANSI.HIDE_CURSOR + this.buildAppend(bounded) + this.buildParkSeq(parking) + ANSI.END_SYNC)\n      this.lastDisplayRows = newDisplayRows\n      this.lineCache = bounded.map(l => l.text)\n      this.hasRendered = true\n      // 区域在此路径从无到有（或 clear 后重建）：屏上几何已变，旧基线\n      // 不再适用（可能来自 clear 窗口期的位置采样），作废等下一响应重建。\n      this.cprBaseline = null\n      this.setParked(parking)\n      this.requestProbe()\n      return\n    }\n\n    const prevDisplayRows = this.lastDisplayRows\n\n    // 行级 diff 资格：行数相同，且**每行**的显示行数（wrap 高度）新旧一致。\n    // 关键不变量：逐行 wrap 高度不变 → 改某行不会让后续行整体上/下移（无级联），\n    // 相对光标步进（cursorDown 按显示行数）才能精确对齐。任一行 wrap 高度变化 →\n    // 会级联错位，回退全量重写（更稳）。允许多行 wrap 行参与增量。\n    //\n    // 宽度刚变过（resize）时禁用 diff：屏上旧帧被终端按新宽 reflow，实际布局\n    // 与 lineCache 的估算可能不一致（部分终端不 reflow / ambiguous 宽度偏差），\n    // 相对步进的增量改写会在错位的行上打补丁 → 旧帧碎片残留叠屏。\n    // 全量重写（回顶 + ERASE_SCREEN_END + 重铺）把不确定性收敛到锚点一处。\n    const canDiff =\n      !widthChanged &&\n      bounded.length === this.lineCache.length &&\n      bounded.every((l, i) => {\n        const cached = this.lineCache[i]\n        return cached !== undefined && this.rowsForLine(l.text) === this.rowsForLine(cached)\n      })\n\n    // 帧首爬升以驻停点为起点：硬件光标模式 caret 驻停时光标不在末行尾\n    // （差 parkedRowsUp 行）；软件光标模式下光标始终在末行尾，parkedRowsUp=0。\n    const climbRows = prevDisplayRows - this.parkedRowsUp\n    const body = canDiff\n      ? this.buildDiff(bounded, climbRows)\n      : this.buildFullRewrite(bounded, climbRows)\n\n    // 帧首隐藏硬件光标（覆盖 overlay 退出后 SHOW_CURSOR 的间隙、帧内防闪）；\n    // 帧末 buildParkSeq 把它搬到输入框软件光标坐标（IME 候选窗锚定硬件光标）。\n    this.stdout.write(ANSI.BEGIN_SYNC + ANSI.HIDE_CURSOR + body + this.buildParkSeq(parking) + ANSI.END_SYNC)\n    this.lastDisplayRows = newDisplayRows\n    this.lineCache = bounded.map(l => l.text)\n    // 区域 display rows 总数变化 = 合法几何变化（输入折行/增行、面板开合、\n    // 动态段高低变化）：旧 CPR 基线按旧几何折算，继续比对会把合法变化误判\n    // 为外来污染 → 恢复性全量重铺按旧几何回顶 → 欠回顶 → 旧帧顶部残留成\n    // 「输入框多一行」重影。rowsUp 漂移守卫只覆盖 caret 下方行数变化，\n    // caret 行自身增行/折行时 rowsUp 不变、守卫漏过——这里按总数变化作废\n    // 基线，下一个探针响应按新几何重建（外部写入不改变引擎几何，仍会被检出）。\n    // hasRendered 在此路径恒为 true（首帧/clear 路径已提前返回）。\n    if (newDisplayRows !== prevDisplayRows) {\n      this.cprBaseline = null\n    }\n    this.setParked(parking)\n    this.requestProbe()\n  }\n\n  /** 从 bounded 行里找 caret 标记行，算驻停点（距末行 display rows + 0-based 列）。 */\n  private computeParking(bounded: readonly LiveRegionLine[]): { rowsUp: number; col: number } | null {\n    const idx = bounded.findIndex(l => l.caretCol != null)\n    if (idx < 0) return null\n    let rowsUp = 0\n    for (let i = idx + 1; i < bounded.length; i++) {\n      const line = bounded[i]\n      if (line === undefined) continue\n      rowsUp += this.rowsForLine(line.text)\n    }\n    const caretLine = bounded[idx]\n    if (caretLine === undefined || caretLine.caretCol == null) return null\n    return { rowsUp, col: caretLine.caretCol }\n  }\n\n  /** 帧末驻停序列：末行尾 → caret 坐标（默认驻停但保持隐藏；env 仅控制可见性）。 */\n  private buildParkSeq(parking: { rowsUp: number; col: number } | null): string {\n    let seq = ''\n    if (parking) {\n      if (parking.rowsUp > 0) seq += cursorUp(parking.rowsUp)\n      seq += cursorToCol(parking.col + 1)\n    }\n    // 默认隐藏（定位不可见，单指针视觉）；RIVET_TUI_HARDWARE_CURSOR=1 时可见化——\n    // 个别终端光标可见才跟踪 IME。无 caret 帧显式 HIDE（防 stray 指针）。\n    if (this.hardwareCursorVisible) seq += parking ? ANSI.SHOW_CURSOR : ANSI.HIDE_CURSOR\n    return seq\n  }\n\n  /** 更新驻停记账（须在 requestProbe 前调用——探针按它折算响应坐标）。 */\n  private setParked(parking: { rowsUp: number; col: number } | null): void {\n    this.parkedRowsUp = parking?.rowsUp ?? 0\n    this.parkedCol = parking?.col ?? null\n  }\n\n  /** H2 路径专用：行未变、caret 变了 → 只发重定位序列（不重绘任何文字）。 */\n  private reparkIfChanged(parking: { rowsUp: number; col: number }): void {\n    if (this.parkedRowsUp === parking.rowsUp && this.parkedCol === parking.col) return\n    let seq = ''\n    // rowsUp 是「距末行的行数」：新驻停点更高（rowsUp 变大）→ 上移，反之 → 下移。\n    const delta = parking.rowsUp - this.parkedRowsUp\n    if (delta > 0) seq += cursorUp(delta)\n    else if (delta < 0) seq += cursorDown(-delta)\n    seq += cursorToCol(parking.col + 1)\n    this.stdout.write(ANSI.BEGIN_SYNC + ANSI.HIDE_CURSOR + seq + (this.hardwareCursorVisible ? ANSI.SHOW_CURSOR : '') + ANSI.END_SYNC)\n    this.setParked(parking)\n    this.requestProbe()\n  }\n\n  /**\n   * 行预算：内容超过 maxRows 时，**优先保留尾部 chrome**（GlanceBar + 输入框 + 提示），\n   * 截断的是中段 dynamic（streaming tail / 工具输出）的较早部分。\n   *\n   * **预算按 display rows 计量**（非行数）：窄窗口下长正文/长输入折行后，\n   * 行数 ≤ maxRows 也可能整帧超出终端高度——全量重写越过屏幕底部触发滚动，\n   * 回顶量与屏上实际布局错位，旧帧正文残留并叠印在 chrome 之下\n   * （小窗口打字时正文\"泄露\"到输入框底下的根因）。不变量：整帧恒 ≤ maxRows\n   * display rows（= min(28, rows-1)），重写永不越底。\n   *\n   * - 全帧 display rows ≤ maxRows：全部保留。\n   * - 未指定 reservedTail：按预算保留前若干行。\n   * - 指定 reservedTail：尾部 N 行恒保留；剩余预算从 dynamic 段尾部回填。\n   *   若 chrome 本身已超 maxRows，仍全部显示——宁可超行，也不能让输入框消失。\n   */\n  private applyRowBudget(lines: readonly LiveRegionLine[], reservedTail?: number): LiveRegionLine[] {\n    if (this.countDisplayRows(lines) <= this.maxRows) return lines.slice()\n    if (reservedTail === undefined || reservedTail <= 0) {\n      const kept: LiveRegionLine[] = []\n      let rows = 0\n      for (const line of lines) {\n        const r = this.rowsForLine(line.text)\n        if (rows + r > this.maxRows) break\n        kept.push(line)\n        rows += r\n      }\n      return kept\n    }\n    const tail = Math.min(reservedTail, lines.length)\n    const tailLines = lines.slice(lines.length - tail)\n    const tailRows = this.countDisplayRows(tailLines)\n    const budget = this.maxRows - tailRows\n    if (budget <= 0) return tailLines.slice()\n    const dynamic = lines.slice(0, lines.length - tail)\n    const kept: LiveRegionLine[] = []\n    let rows = 0\n    for (let i = dynamic.length - 1; i >= 0; i--) {\n      const line = dynamic[i]\n      if (line === undefined) continue\n      const r = this.rowsForLine(line.text)\n      if (rows + r > budget) break\n      kept.unshift(line)\n      rows += r\n    }\n    return [...kept, ...tailLines]\n  }\n\n  /** Append 路径：行间 `\\n`，尾行不带 `\\n`（光标常驻最后一行末尾）。 */\n  private buildAppend(bounded: readonly LiveRegionLine[]): string {\n    let out = ''\n    for (const [i, line] of bounded.entries()) {\n      out += line.text\n      if (i < bounded.length - 1) out += '\\n'\n    }\n    return out\n  }\n\n  /** 相对光标回到 live region 顶部显示行（光标当前在最后一个显示行）。 */\n  private moveToTop(prevDisplayRows: number): string {\n    return prevDisplayRows > 1 ? cursorUp(prevDisplayRows - 1) : ''\n  }\n\n  /**\n   * 全量重写：回顶 → 擦到屏幕末（覆盖旧的所有显示行，含 wrap）→ 重写全部行。\n   * 尾行不带 `\\n`，光标停在最后一行末尾。\n   */\n  private buildFullRewrite(bounded: readonly LiveRegionLine[], prevDisplayRows: number): string {\n    let out = this.moveToTop(prevDisplayRows)\n    out += '\\r' + ANSI.ERASE_SCREEN_END\n    for (const [i, line] of bounded.entries()) {\n      out += line.text\n      if (i < bounded.length - 1) out += '\\n'\n    }\n    return out\n  }\n\n  /**\n   * 行级 diff（结构未变 + 每行 wrap 高度未变时调用，见 canDiff）：\n   * 回顶后逐行处理——变化行清除其全部显示行后重写；未变行只按显示行数 cursorDown 跳过。\n   * 不写任何 `\\n`（cursorDown 在底行会被 clamp，不触发滚屏）。\n   *\n   * 光标步进不变量：每次迭代开始时光标位于「逻辑行 i 的首个显示行」，\n   * 处理结束时（cursorDown 之前）位于「逻辑行 i 的最后一个显示行」，\n   * 再 cursorDown(1) 进入下一逻辑行首行。变化行与未变行两条分支都满足该不变量。\n   */\n  private buildDiff(bounded: readonly LiveRegionLine[], prevDisplayRows: number): string {\n    let out = this.moveToTop(prevDisplayRows)\n    for (const [i, line] of bounded.entries()) {\n      const text = line.text\n      const rows = this.rowsForLine(text) // == rowsForLine(lineCache[i])，canDiff 已保证\n      out += '\\r'\n      if (this.lineCache[i] !== text) {\n        // 变化行：先擦除其占用的全部显示行（含 wrap 续行），再写入新内容。\n        // 仅擦首行会让旧的 wrap 续行残留为 ghost。\n        out += ANSI.ERASE_LINE\n        for (let k = 1; k < rows; k++) {\n          out += cursorDown(1) + '\\r' + ANSI.ERASE_LINE\n        }\n        if (rows > 1) out += cursorUp(rows - 1) // 回到本行首行再写\n        out += text // 自动 wrap 至 rows 个显示行，光标落在最后一个显示行末\n      } else if (rows > 1) {\n        // 未变的多行 wrap 行：不重写，仅下移到其最后一个显示行。\n        out += cursorDown(rows - 1)\n      }\n      if (i < bounded.length - 1) out += cursorDown(1)\n    }\n    return out\n  }\n\n  /**\n   * 清空 live region（擦除但不回滚 scrollback）。\n   * 用于流式输出完成、切换到新 turn 时。\n   *\n   * 光标常驻协议下，光标在最后一个显示行——回顶后擦到屏幕末，光标停在\n   * 区域起始处。后续 append/commit 从这里开始写，干净无空白带。\n   */\n  clear(): void {\n    if (this.probeSuppressed) return\n    this.reconcileWidth()\n    if (this.lastDisplayRows === 0) return\n    this.stdout.write(ANSI.HIDE_CURSOR + this.moveToTop(this.lastDisplayRows - this.parkedRowsUp) + '\\r' + ANSI.ERASE_SCREEN_END)\n    this.lastDisplayRows = 0\n    this.lineCache = []\n    this.setParked(null)\n    // 区域已离屏：污染标记随帧状态一起作废（noteCpr 此时只更新基线不判污染）。\n    this.polluted = false\n  }\n\n  /**\n   * 擦除 live region 并把光标停在其起始行——为向 scrollback commit 内容腾位。\n   *\n   * 正确的 mid-stream commit 协议：\n   *   live.clearForCommit() → commit.write(...) → live.render(...)\n   *\n   * cursor-resident 协议下与 clear() 行为一致（光标都回到区域起始处）。\n   */\n  clearForCommit(): void {\n    this.clear()\n  }\n\n  /**\n   * 渲染单行动态文本（如 streaming 行、thinking 指示器）。\n   * 简化版：擦除上一帧内容 → 写入新内容。\n   * @param text - 该行的 ANSI 格式化文本\n   */\n  renderLine(text: string): void {\n    this.render([{ text }])\n  }\n\n  /** 重置渲染状态（用于 rewind 等需要全量重绘的场景） */\n  reset(): void {\n    this.lastDisplayRows = 0\n    this.lineCache = []\n    this.hasRendered = false\n    this.setParked(null)\n  }\n}\n"
